// Actions-only current private-bus API. Notification fields remain DATA.
#[tokio::test]
async fn im_send_options_http_digest_invalid_or_conflicting_source_has_nonce_bound_no_intent_observation(){
    let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/im-outbox";
    for extra in [serde_json::json!({"info_type":"Subtype","notification_digest":"display"}),serde_json::json!({"notification_digest":"display","notifications":[]}),serde_json::json!({"notification_digest":"bad\u{0000}value"}),serde_json::json!({"notification_digest":"x".repeat(65537)})]{
        let mut request=serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"recipient":"1_2","content":"actual body","consent":true,"write_consent":true});for(key,value)in extra.as_object().unwrap(){request[key]=value.clone();}
        let(status,headers,body)=account_request(&served,reqwest::Method::POST,path,Some(request),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);let value:serde_json::Value=serde_json::from_str(&body).unwrap();assert_eq!(value["im_send_admission"],"not_admitted");assert_eq!(value["nonce_tag"].as_str().unwrap().len(),64);assert!(!body.contains("display"));
    }
}
#[tokio::test]
async fn im_send_options_http_original_string_metadata_and_exact_online_key_are_not_sdk_or_write_grants(){
    let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let mut config=im_runtime_config_json(&cert.root);config["profile"]["im_send"]=serde_json::json!({"send_text":true,"send_info":true});let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":config})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);let path=format!("/api/non-3gpp/accounts/{line}/im-outbox");
    let common=serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"recipient":"1_2","content":"body","consent":true,"write_consent":true});
    for extra in [serde_json::json!({"notification_digest":"display","parameters":[{"key":b"userData".to_vec(),"value":[]},{"key":b"OnlineMsg".to_vec(),"value":b"01".to_vec()},{"key":b"imdnId".to_vec(),"value":b"opaque".to_vec()}]}),serde_json::json!({"notifications":[{"key":b"OnlineMsg".to_vec(),"value":b"false".to_vec()}]})]{let mut request=common.clone();for(key,value)in extra.as_object().unwrap(){request[key]=value.clone();}let(status,headers,body)=account_request(&served,reqwest::Method::POST,&path,Some(request),Some(&cookie)).await;assert_eq!(status,StatusCode::SERVICE_UNAVAILABLE);no_store(&headers);no_secrets(&body);assert!(body.contains("app_account_im_send_scope_invalid"));let value:serde_json::Value=serde_json::from_str(&body).unwrap();assert_eq!(value["im_send_admission"],"not_admitted");}
    assert!(state.app.app_accounts.im_send_history(&line,128).unwrap().is_empty());let snapshot=state.app.app_accounts.get(&line,100).await.unwrap();assert_eq!(snapshot.phase,"stopped");assert!(!snapshot.outbound_authorized&&!snapshot.incoming_message_ready&&!snapshot.incoming_call_ready);
}
